+                    }
+
+                    for (int i = 0; i < result.getGetMessageResultList().size(); i++) {
+                        GetMessageResult getMessageResult = result.getGetMessageResultList().get(i);
+                        PopConsumerRecord popConsumerRecord = result.getPopConsumerRecordList().get(i);
