+            ColumnFamilyOptions popStateOptions = new ColumnFamilyOptions().optimizeForSmallDb();
+            this.cfOptions.add(defaultOptions);
+            this.cfOptions.add(popStateOptions);
+
+            this.options = new DBOptions()
